from lib import *
S = SS('h13')
steps = [
    step("MAX_CONCURRENT_STREAMS 是服务端在连接开头的 SETTINGS 帧里告诉客户端的。服务端不设置时,第一个 SETTINGS 只有 MAX_FRAME_SIZE=16384;用 grpc.MaxConcurrentStreams(4) 后变成 MAX_FRAME_SIZE=16384 MAX_CONCURRENT_STREAMS=4。不设置等于不限制(读 server.go:传 0 会变成 MaxUint32,http2_server.go 里只有不等于 MaxUint32 才发这一项)。", t=tl(S(1)), done=lidx(S(1), 'MaxConcurrentStreams(4)'), mark=lidx(S(1), 'MaxConcurrentStreams(0)'), b=bars([['不设置时 SETTINGS 里的项数', 1, '1(MAX_FRAME_SIZE)'], ['MaxConcurrentStreams(4) 时', 2, '2(多了 MAX_CONCURRENT_STREAMS=4)']], 3, mark=[0], done=[1]), kv=KV([['不设置', '不发,等于不限制'], ['设为 4', 'SETTINGS: MAX_CONCURRENT_STREAMS=4'], ['谁来执行', '客户端拿到后自己排队(见下)']], ['设为 4'])),
    step("一条连接上同时发 20 个调用,每个 handler 睡 200 ms:不限制时服务端同时处理的峰值 20,总耗时 202.2 ms,前 100 ms 内客户端发出了 20 个 HEADERS;限制为 4 时峰值 4,总耗时 1007.1 ms,前 100 ms 内客户端只发出了 4 个 HEADERS,完成时刻每 200 ms 一批,每批 4 个,一共 5 批。RST_STREAM 一个都没有——超出的调用没有被服务端拒绝,而是客户端自己把它们留在本地排队,等有流结束、空出名额再发。", t=tl(S(2)), done=lidx(S(2), '限制 4:'), mark=lidx(S(2), '不限制:'), b=bars([['不限制:服务端同时处理的峰值', 20, '20'], ['限制 4:服务端同时处理的峰值', 4, '4'], ['限制 4:总耗时 ms', 1007.1, '1007.1'], ['不限制:总耗时 ms', 202.2, '202.2']], 1050, mark=[0, 3], done=[1, 2]), kv=KV([['不限制', '20 个并发,202.2 ms'], ['限制 4', '4 个并发,5 批,1007.1 ms'], ['超出的调用', '客户端本地排队,没有 RST_STREAM']], ['超出的调用'])),
    step("排队的时间算在调用的 deadline 里。限制 4、handler 200 ms、20 个调用各带 500 ms 的 deadline,重复了 3 轮,每轮都是成功 8 个、DeadlineExceeded 12 个。服务端 handler 实际被调用的次数(14、12、13)比成功数多——因为第三批在 400 ms 左右发出、500 ms 到期被取消(客户端发 RST_STREAM,3 轮分别是 8、7、7 个);另外在 500 ms 附近,排队的调用与被取消的流同时到期,会有 3 到 4 个(各轮 4、3、3 个)在 450 ms 之后才发出 HEADERS,这部分每轮不同,是竞争。排在后面的调用不会因为服务端慢而收到“服务端忙”的错误,只会收到自己的 DeadlineExceeded。", t=tl(S(3)), done=lidx(S(3), '第 3 轮'), mark=lidx(S(3), '第 1 轮'), b=bars([['成功', 8, '8'], ['DeadlineExceeded', 12, '12']], 14, mark=[1], done=[0]), kv=KV([['每轮结果', '成功 8,DeadlineExceeded 12(3 轮一致)'], ['handler 被调用', '14、12、13 次(每轮不同)'], ['450 ms 之后才发出的 HEADERS', '4、3、3 个(每轮不同)']], ['每轮结果'])),
    step("限制是“每条连接”的(读 server.go 的注释:to each ServerTransport)。40 个并发调用、handler 100 ms、每条连接限制 4,客户端用应用层自己建的多条连接轮流分配:1 条连接峰值 4,总耗时 1013.3 ms;2 条的峰值是 8,总耗时 509.1 ms;4 条的峰值是 16,总耗时 306.4 ms;10 条的峰值是 40,总耗时 102.3 ms。连接数乘以每条连接的限制就是并发上限,总耗时大致按批数缩短。", t=tl(S(4)), done=lidx(S(4), '10 条连接'), mark=lidx(S(4), ' 1 条连接'), b=bars([['1 条连接 总耗时 ms', 1013.3, '1013.3'], ['2 条连接', 509.1, '509.1'], ['4 条连接', 306.4, '306.4'], ['10 条连接', 102.3, '102.3']], 1050, mark=[0], done=[1, 2, 3]), kv=KV([['1 条', '峰值 4,1013.3 ms'], ['4 条', '峰值 16,306.4 ms'], ['10 条', '峰值 40,102.3 ms']], ['4 条'])),
    step("长流会一直占着名额:限制 2,先开 2 个不结束的服务端流,再发一个 Unary 调用。600 ms 之后这个 Unary 还没有到达服务端(到达次数 0,说明还在客户端排队);长流释放之后它在开始后 603.8 ms 才完成,服务端 handler 只被调用了 1 次。名额按流数计,不管流在传多少数据——几个长期不结束的流(订阅、双向流)就能把一条连接的名额占满,让同一条连接上的普通调用无限期排队。", t=tl(S(5)), done=lidx(S(5), '长流结束'), mark=lidx(S(5), '600 ms 后'), b=bars([['占满名额 600 ms 后到达服务端的 Unary 次数', 0, '0'], ['释放后 Unary 完成用时 ms', 603.8, '603.8']], 650, mark=[0], done=[1]), kv=KV([['限制', '2,被 2 个长流占满'], ['普通 Unary', '客户端排队,600 ms 内没到服务端'], ['长流释放后', '603.8 ms 完成']], ['普通 Unary'])),
    step("不设限制时,全新的连接上直接发 300 个并发调用(handler 200 ms,没有预热):服务端同时处理的峰值 300,总耗时 210.4 ms。读源码:客户端在 SETTINGS 里没看到 MAX_CONCURRENT_STREAMS 时把配额设成 MaxUint32(http2_client.go 里 isFirst 的分支),实测没有被卡在 100(源码里 defaultMaxStreamsClient = 100 是拿到服务端 SETTINGS 之前的初始值,这里没有观察到它起作用)。", t=tl(S(6)), done=lidx(S(6), '全新的连接上'), mark=lidx(S(6), '全新的连接上'), b=bars([['服务端同时处理的峰值', 300, '300']], 320, done=[0]), kv=KV([['服务端不设限制', '300 个并发全部同时处理'], ['总耗时', '210.4 ms'], ['客户端默认配额 100', '实测没有卡在 100']], ['服务端不设限制'])),
]
A = mkarth('h13', 13, 'gRPC,MaxConcurrentStreams,并发流,HTTP/2,排队,SETTINGS,Go,真实验证,动画演示',
    '实测 gRPC 的 max_concurrent_streams:服务端在 SETTINGS 帧里公布,客户端自己排队而不是被拒绝;排队时间算在 deadline 里;限制是每条连接的;长流会占满名额让普通调用无限期排队。',
    '一条 HTTP/2 连接上最多能同时跑多少个调用?超过了是被服务端拒绝还是排队?排队的时间算谁的?这篇用 MaxConcurrentStreams 和抓包代理逐项实测。',
    [('4 个 HEADERS', '限制 4 时,前 100 ms 内客户端实际发出的请求数(其余 16 个在客户端排队)'), ('1007.1 ms', '限制 4 时 20 个 200 ms 调用的总耗时(不限制是 202.2 ms)'), ('8 成功 / 12 超时', '排队 + 500 ms deadline 时每一轮的结果(3 轮一致)')],
    [('这个限制在哪', '<p>HTTP/2 的 SETTINGS_MAX_CONCURRENT_STREAMS 是接收方告诉发送方“我最多同时接受这么多流”。grpc-go 服务端默认不设置(不限制),用 grpc.MaxConcurrentStreams(n) 设置。</p>'),
     ('超出的怎么办', '<p>客户端读到这个设置后,同时在途的流达到上限就把新调用留在本地排队,有流结束再发。线上没有 RST_STREAM,服务端也不知道有人在排队。</p>'),
     ('排队与 deadline', '<p>排队的时间算在调用自己的 deadline 里:排队太久得到的是 DeadlineExceeded,不是“服务端忙”。deadline 到期的瞬间,有的调用刚好发出又被取消,每次运行数量略有不同。</p>'),
     ('每条连接', '<p>限制作用在每条连接上。客户端建 n 条连接,并发上限就是 n 倍;但每多一条连接就多一份连接的开销(第 38 篇讨论连接池)。</p>'),
     ('长流占名额', '<p>一个流从开始到结束都占一个名额,不管它传了多少数据。几个长期存活的流(订阅、双向流)可能把名额占满,使同一条连接上的普通调用排队。</p>'),
     ('不设限制', '<p>服务端不设置时客户端的配额是 MaxUint32,300 个并发调用全部同时在处理。限制是保护服务端的手段,不是默认存在的。</p>')],
    steps,
    [ENV_H + '。“服务端同时处理的峰值”是 handler 里的原子计数器;HEADERS、RST_STREAM 数量和时刻来自代理对 HTTP/2 帧的解析;第三节重复了 3 轮,因为 deadline 到期瞬间的竞争每轮不同;“超出的调用在客户端排队”由“前 100 ms 内只发出 4 个 HEADERS、没有 RST_STREAM、服务端到达次数为 0”间接得出,并核对了 grpc-go 源码(http2_client.go 的 streamQuota 与 waitingStreams)',
     '没有验证:其它语言的客户端是否也在本地排队;服务端降低限制(SETTINGS 动态变小)时已有流的处理;多个客户端同时连一个服务端时的公平性;负载均衡策略下每个子连接各自的配额(第 14 篇);把 MaxConcurrentStreams 设得很大时的内存与 goroutine 开销(第 31 篇)'],
    'max_concurrent_streams')
